@config.patch(implicit_fallbacks=True)
def test_no_align_for_custom_op_2d(self):
    def slice2d(x):
        return (3 * x)[..., 1:-15]

    def slice2d_meta(x):
        return torch.empty_like(x)[..., 1:-15]

    define_custom_op_for_test("slice2d", slice2d, slice2d_meta)

    def fn(x):
        a = torch.nn.functional.relu(x)
        b = torch.ops.test.slice2d(a)
        c = torch.cos(b)
        return c

    x = torch.randn(1024, 1024 + 16, device=self.device)
    self.common(fn, (x,), check_lowp=False)

@config.patch(implicit_fallbacks=True, alignment_asserts=True)
@skip_if_cpp_wrapper(
    "Inductor does not generate alignment assertion for cpp_wrapper right now"
)
def test_incorrect_meta_for_custom_op_2d(self):
    def slice2d(x):
        return (3 * x)[..., 1:-15]

    def slice2d_meta(x):
        return torch.empty_like(x)[..., 0:-16]

    define_custom_op_for_test("slice2d_incorrect_meta", slice2d, slice2d_meta)

    def fn(x):
        a = torch.nn.functional.relu(x)
        b = torch.ops.test.slice2d_incorrect_meta(a)
        c = torch.cos(b)
        return c

    x = torch.randn(1024, 1024 + 16, device=self.device)

    expected_error = "Expect the tensor to be 16 bytes aligned. Fail due to storage_offset=1 itemsize=4"
    with self.assertRaisesRegex(AssertionError, expected_error):
        self.common(fn, (x,), check_lowp=False)

def test_compile_decorator(self):
    @torch.compile
    def foo(x):
        return torch.sin(x) + x.min()

    @torch.compile(mode="reduce-overhead")
    def bar(x):
        return x * x

    for _ in range(3):
        foo(torch.full((3, 4), 0.7, device=GPU_TYPE))
        bar(torch.rand((2, 2), device=GPU_TYPE))

@unittest.skipIf(not HAS_CPU or not HAS_GPU, "requires CPU and GPU")
@decorateIf(
    unittest.expectedFailure,
    lambda params: params["benchmarker_cls"] is Benchmarker
    and params["device"] == GPU_TYPE,
)
@parametrize("benchmarker_cls", ALL_BENCHMARKER_CLASSES)
@parametrize("device", (GPU_TYPE, "cpu"))
def test_benchmark_smoke(self, benchmarker_cls, device):
    benchmarker = benchmarker_cls()
    (fn, fn_args, fn_kwargs), _ = self.make_params(device)
    timing = benchmarker.benchmark(fn, fn_args, fn_kwargs)
    self.assertGreater(timing, 0)
    self.assertEqual(self.get_counter_value(benchmarker_cls, "benchmark"), 1)
    self.assertEqual(
        self.get_counter_value(
            benchmarker_cls, "benchmark_cpu" if device == "cpu" else "benchmark_gpu"
        ),
        1,
    )

