    ]:

        def fn1(x):
            return (x.view(size2) + 1,)

        def fn2(x):
            return ((x * 2).view(size2) + 1,)

        self.common(fn1, (torch.randn(size1),))
        self.common(fn2, (torch.randn(size1),))

