@functools.lru_cache(maxsize=1)
def _get_core_nums():
    return _obtain_and_limit_cube_vector_core_num()

def __getattr__(name):
    if name in ("prop", "num_cube_core", "num_vector_core"):
        prop, cube, vec = _get_core_nums()
        return {"prop": prop, "num_cube_core": cube, "num_vector_core": vec}[name]
    raise AttributeError(f"module {__name__!r} has no attribute {name!r}")

def codegen_template(self, template_node, epilogue_nodes, only_gen_src_code=False):
    if isinstance(
        template_node.node,
        FlexAttentionDispatchTemplateBuffer,
    ):
        if only_gen_src_code:
            raise NotImplementedError(
                "source-only codegen is unsupported for composite "
                "FlexAttention dispatch templates"
            )
        return codegen_flex_attention_dispatch_template(
            self, template_node, epilogue_nodes
        )
    _, (numel, rnumel) = template_node.group
    assert rnumel == 1
    kernel, render = template_node.node.make_kernel_render(template_node.node)
    with kernel:
        if not only_gen_src_code:
            for node in [template_node, *epilogue_nodes]:
                node.mark_run()
        partial_code = render()
        # Handle both legacy "<STORE_OUTPUT>" (without index) and torch
        # 2.10's "<STORE_OUTPUT_N>" (with index) subgraph body naming.
        if "<STORE_OUTPUT>" in kernel.subgraph_bodies:
            with kernel.set_subgraph_body("<STORE_OUTPUT>"):
                for node in epilogue_nodes:
                    node.codegen(kernel.split_and_set_ranges(node.get_ranges()))
        # torch 2.10+ creates indexed store_output subgraphs.
        if hasattr(kernel, "get_store_output_count"):
            num_store_subgraphs = kernel.get_store_output_count()
            for i in range(num_store_subgraphs):
                subgraph_name = kernel._get_store_output_subgraph_name(i)
                if subgraph_name in kernel.subgraph_bodies:
                    with kernel.set_subgraph_body(subgraph_name):
                        for node in epilogue_nodes:
                            node.codegen(kernel.split_and_set_ranges(node.get_ranges()))

    if not isinstance(partial_code, str):
        partial_code.finalize_hook("<DEF_KERNEL>")
        partial_code.finalize_hook("<ARGDEFS>", strict=False)
    # finalize must be called after adding epilogue above
    with V.set_kernel_handler(kernel):
        # Finalize legacy "<STORE_OUTPUT>" (without index) if present.
        has_store_output = "<STORE_OUTPUT>" in kernel.subgraph_bodies
        if has_store_output and not isinstance(partial_code, str):
            with kernel.set_subgraph_body("<STORE_OUTPUT>"):
                partial_code.finalize_hook("<STORE_OUTPUT>")
        # Now safe to extract the final source code.
        # Use finalize_remaining() to catch any leftover hooks (e.g.
        # torch 2.10's indexed "<STORE_OUTPUT_N>" hooks).
        if isinstance(partial_code, str):
            src_code = partial_code
        elif hasattr(partial_code, "finalize_remaining"):
            src_code = partial_code.finalize_remaining()
        else:
            src_code = partial_code.code
        node_schedule = [template_node, *epilogue_nodes]

        if config.benchmark_kernel:
            num_gb = kernel.estimate_kernel_num_bytes() / 1e9
            grid_args = V.graph.sizevars.optimization_hints(kernel.call_sizes)
            assert kernel.meta is not None, "meta is None"
            grid = kernel.grid_fn(*grid_args, kernel.meta)

            src_code = (
                f"{kernel.imports_for_benchmark_kernel()}\n"
                f"{src_code}\n"
                f"{kernel.codegen_kernel_benchmark(num_gb).getvalue()}"
            )

        if only_gen_src_code:
            return src_code
        traced_graph_hash = None
        kernel_name, src_code = self.define_kernel(src_code, node_schedule, kernel, traced_graph_hash)

    self.codegen_comment(node_schedule)
    kernel.call_kernel(kernel_name, template_node.node)

    V.graph.removed_buffers |= kernel.removed_buffers
    V.graph.inplaced_to_remove |= kernel.inplaced_to_remove
    self.scheduler.free_buffers()
    return None

@register_custom_pass(PassType.PRE)
def dtype_optimal_pass(graph: torch.fx.Graph) -> None:
    """Narrow unnecessary int64 to int32: if the values of torch.arange or to(int64)
    fit safely in int32, downgrade the dtype to cut memory traffic and compute cost."""
    cast_dtype_limit = [torch.float32, torch.int32, torch.bool, torch.int16, torch.int8]
    changed = False
    for node in list(graph.nodes):  # use list to avoid mutating while iterating
        if (
            node.op == "call_function"
            and node.target == torch.arange
            and node.kwargs.get("dtype", None) == torch.int64
        ):
            # step 1: extract start/end/step dynamically (handles different args lengths)
            args_len = len(node.args)
            start = 0
            end = None
            step = 1
            if args_len == 1:
                end = node.args[0]  # arange(end)
            elif args_len == 2:
                start = node.args[0]
                end = node.args[1]  # arange(start, end)
            elif args_len >= 3:
                start = node.args[0]
                end = node.args[1]
                step = node.args[2]  # arange(start, end, step)
            # merge kwargs overrides (e.g. a user-specified kwargs['start'])
            start = node.kwargs.get("start", start)
            end = node.kwargs.get("end", end)
            step = node.kwargs.get("step", step)
            # if end is None, treat it as unbounded and skip (rare, but safe)
            if end is None:
                continue
            # Normalize start/end/step (symbolic allowed); elements always lie in
            # [start, end), so downgrade is safe once both bounds provably fit int32; step must be a nonzero int.
            r_start = resolve_size_arg(start)
            r_end = resolve_size_arg(end)
            r_step = resolve_size_arg(step)
            if r_start is None or r_end is None or r_step is None:
                continue
            if not isinstance(r_step, int) or r_step == 0:
                continue
            if statically_fits_int32(r_start, r_end):
                node.kwargs = {**node.kwargs, "dtype": torch.int32}
                changed = True
        if node.op == "call_method":
            input_node = node.args[0]
            input_fake = (
                input_node.meta.get("example_value", None)
                if hasattr(input_node, "meta")
                else None
            )
            input_dtype = (
                input_fake.dtype if isinstance(input_fake, torch.Tensor) else None
            )
            target_dtype = (
                node.args[1] if len(node.args) > 1 else node.kwargs.get("dtype", None)
            )
            if (
                input_dtype in cast_dtype_limit
                and node.target == "to"
                and target_dtype == torch.int64
            ):
                if len(node.args) > 1:
                    node.args = (node.args[0], torch.int32)  # update the positional dtype
                else:
                    node.kwargs = {
                        **node.kwargs,
                        "dtype": torch.int32,
                    }  # update the kwargs dtype
                changed = True
    eliminate_dead_code(graph, changed, dtype_optimal_pass.__name__, False)

def check_multiple_devices_or_any_cpu_nodes(
    device_node_mapping: dict[torch.device, torch.fx.Node],
) -> str | None:
    # meta tensors are supported since there is no compute
    device_node_mapping.pop(torch.device("meta"), None)

    # dynamo cudagraph does not support graph partition
    if is_using_cudagraph_partition():
        # graph partition supports splitting on cpu op. So we can ignore cpu nodes.
        device_node_mapping.pop(torch.device("cpu"), None)

    if cpu_node := device_node_mapping.get(torch.device("cpu")):
        msg = f"cpu device ({cpu_node.name})"
        if stack_trace := _get_use_stack_trace(cpu_node):
            return format_default_skip_message(f"{msg}. Found from : \n {stack_trace}")

        return format_default_skip_message(msg)

    if (
        len(device_node_mapping) == 1
        and next(iter(device_node_mapping.keys())).type == "cuda"
    ):
        return None

    keys_repr = (repr(key) for key in device_node_mapping)
    return format_default_skip_message(f"multiple devices: {', '.join(keys_repr)}")

def check_lowering_disable_cudagraph(
    device_node_mapping: dict[torch.device, torch.fx.Node],
) -> str | None:
    return (
        check_caching_allocator_for_cudagraphs()
        or check_multiple_devices_or_any_cpu_nodes(device_node_mapping)
    )

@contextlib.contextmanager
def force_fallback(op: torch._ops.OpOverload):
    """
    A context manager to force fallback an op. Used in unit test
    for FallbackKernel.
    """
    assert isinstance(op, torch._ops.OpOverload), (
        "Only OpOverload to make the clean up easier"
    )
    old_handler = lowerings.get(op)
    try:
        register_lowering(op)(fallback_handler(op))
        yield
    finally:
        if old_handler:
            lowerings[op] = old_handler
        else:
            lowerings.pop(op)

def infer_device(self, *fn_args: Any, **fn_kwargs: Any) -> torch.device:
    inferred_device: torch.device | None = None
    for arg_or_kwarg in chain(fn_args, fn_kwargs.values()):
        # Some callables take nested structures as arguments so use the
        # flattened form to find any tensors
        for arg_or_kwarg_leaf in pytree.tree_leaves(arg_or_kwarg):
            if not isinstance(arg_or_kwarg_leaf, torch.Tensor):
                continue
            if inferred_device is None:
                inferred_device = arg_or_kwarg_leaf.device
            elif arg_or_kwarg_leaf.device != inferred_device:
                raise ValueError(
                    "Can't safely infer the device type of `fn` with multiple device types in `fn_args` and `fn_kwargs`!"
                )

    if inferred_device is None:
        raise ValueError(
            "Can't safely infer the device type of `fn` with no device types"
            " in `fn_args` or `fn_kwargs`. Use a direct benchmarking method instead e.g. "
            "`Benchmarker.benchmark_cpu` or `Benchmarker.benchmark_gpu`."
        )

    return inferred_device

@time_and_count
def benchmark_gpu(self: Self, *args: Any, **kwargs: Any) -> float:
    raise NotImplementedError

@may_distort_benchmarking_result
@time_and_count
@gpu_benchmark_lock
# pyrefly: ignore [bad-override]
def benchmark_gpu(
    self: Self,
    _callable: Callable[[], Any],
    is_vetted_benchmarking: bool = False,
    **kwargs: Any,
) -> float:
    """Benchmark the GPU callable, `_callable`, and return the runtime, in milliseconds.

    Arguments:
    - _callable: The GPU callable to benchmark.

    Keyword Arguments:
    - quantiles: Optionally, a tuple of floats denoting the requested quantiles.
    - return_mode: Optionally, the requested return mode. Currently, Triton's
    `do_bench` supports min, max, mean, and median return modes.
    - **kwargs: Additional kwargs passed to Triton's `do_bench`.

    Returns:
    - The runtime of `callable`, in milliseconds. If `kwargs["quantiles"]` is specified,
    this is the first requested quantile. Else, if `kwargs["return_mode"]` is specified,
    this is the requested return mode. Otherwise, this is the median.
    """
    if not is_vetted_benchmarking:
        may_ban_benchmarking()

    do_bench_params = inspect.signature(self.triton_do_bench).parameters
    for kwarg in list(kwargs.keys()):
        if kwarg not in do_bench_params:
            del kwargs[kwarg]
    try:
        if "quantiles" in kwargs:
            return self.triton_do_bench(_callable, **kwargs)[0]
        elif "return_mode" in kwargs:
            return self.triton_do_bench(_callable, **kwargs)
        return self.triton_do_bench(_callable, **kwargs, return_mode="median")
    except Exception as e:
        # ErrorInvalidConfiguration
        # Return inf to skip this config during autotuning
        error_str = str(e).lower()
        if "invalid configuration" in error_str:
            logger.warning(
                "Skipping benchmark due to invalid configuration error: %s",
                error_str,
            )
            return float("inf")
        raise

@impl(m, "npu_gather_backward")
def npu_gather_backward__meta(grad, self_size, dim, index, sparse_grad):
    if sparse_grad:
        self_dim = len(self_size)
        if self_dim == 0:
            return torch.sparse_coo_tensor(
                torch.empty((0, grad.numel()), dtype=index.dtype, device=grad.device),
                grad,
                self_size,
                device=grad.device,
            )
        if grad.dim() == 0:
            return torch.sparse_coo_tensor(
                index.view(1, 1),
                grad,
                self_size,
                device=grad.device,
            )

        sparse_ind = torch.empty((self_dim, grad.numel()), dtype=torch.long, device=grad.device)
        grad_numel = grad.numel()
        if grad_numel > 0:
            n_above = grad_numel
            n_below = 1
            if dim < 0:
                dim += self_dim
            for i in range(self_dim):
                n_above //= grad.size(i)
                if i == dim:
                    sparse_ind[i] = index.reshape(-1)
                else:
                    sparse_ind[i] = (
                        torch.arange(grad.size(i), dtype=torch.long, device=grad.device)
                        .unsqueeze(1)
                        .expand(grad.size(i), n_above)
                        .reshape(-1)
                        .repeat(n_below)
                    )
                n_below *= grad.size(i)
        return torch.sparse_coo_tensor(
            sparse_ind,
            grad.reshape(-1),
            self_size,
            device=grad.device,
        )
    return torch.empty(self_size, dtype=grad.dtype, device=grad.device)

def _wrapper_cuda(fn):
    @wraps(fn)
    def decorated(*args, **kwargs):
        replace_int = fn.__name__ in ['to', 'to_empty']
        if args:
            args_new = list(args)
            args = _replace_cuda_to_npu_in_list(args_new, replace_int)
        if kwargs:
            for device_arg in device_kwargs_list:
                device = kwargs.get(device_arg, None)
                if device is not None:
                    _replace_cuda_to_npu_in_kwargs(kwargs, device_arg, device)
            device_ids = kwargs.get('device_ids', None)
            if isinstance(device_ids, list):
                kwargs["device_ids"] = _replace_cuda_to_npu_in_list(device_ids, replace_int)
            elif isinstance(device_ids, tuple):
                kwargs["device_ids"] = tuple(_replace_cuda_to_npu_in_list(list(device_ids), replace_int))
        return fn(*args, **kwargs)

    return decorated

def _device_wrapper(enter_fn, white_list):
    for fn_name in white_list:
        fn = getattr(enter_fn, fn_name, None)
        if fn:
            setattr(enter_fn, fn_name, _wrapper_cuda(fn))

def codegen_template(self, template_node, epilogue_nodes, only_gen_src_code=False):
    if isinstance(
        template_node.node,
        FlexAttentionDispatchTemplateBuffer,
    ):
        if only_gen_src_code:
            raise NotImplementedError(
                "source-only codegen is unsupported for composite "
                "FlexAttention dispatch templates"
            )
        return codegen_flex_attention_dispatch_template(
            self, template_node, epilogue_nodes
        )
    _, (numel, rnumel) = template_node.group
    assert rnumel == 1
    kernel, render = template_node.node.make_kernel_render(template_node.node)
    with kernel:
        if not only_gen_src_code:
            for node in [template_node, *epilogue_nodes]:
                node.mark_run()
        partial_code = render()
        # Handle both legacy "<STORE_OUTPUT>" (without index) and torch
        # 2.10's "<STORE_OUTPUT_N>" (with index) subgraph body naming.
        if "<STORE_OUTPUT>" in kernel.subgraph_bodies:
            with kernel.set_subgraph_body("<STORE_OUTPUT>"):
                for node in epilogue_nodes:
                    node.codegen(kernel.split_and_set_ranges(node.get_ranges()))
        # torch 2.10+ creates indexed store_output subgraphs.
        if hasattr(kernel, "get_store_output_count"):
            num_store_subgraphs = kernel.get_store_output_count()
            for i in range(num_store_subgraphs):
                subgraph_name = kernel._get_store_output_subgraph_name(i)
                if subgraph_name in kernel.subgraph_bodies:
                    with kernel.set_subgraph_body(subgraph_name):
                        for node in epilogue_nodes:
                            node.codegen(kernel.split_and_set_ranges(node.get_ranges()))

    if not isinstance(partial_code, str):
        partial_code.finalize_hook("<DEF_KERNEL>")
        partial_code.finalize_hook("<ARGDEFS>", strict=False)
    # finalize must be called after adding epilogue above
    with V.set_kernel_handler(kernel):
        # Finalize legacy "<STORE_OUTPUT>" (without index) if present.
        has_store_output = "<STORE_OUTPUT>" in kernel.subgraph_bodies
        if has_store_output and not isinstance(partial_code, str):
            with kernel.set_subgraph_body("<STORE_OUTPUT>"):
                partial_code.finalize_hook("<STORE_OUTPUT>")
        # Now safe to extract the final source code.
        # Use finalize_remaining() to catch any leftover hooks (e.g.
        # torch 2.10's indexed "<STORE_OUTPUT_N>" hooks).
        if isinstance(partial_code, str):
            src_code = partial_code
        elif hasattr(partial_code, "finalize_remaining"):
            src_code = partial_code.finalize_remaining()
        else:
            src_code = partial_code.code
        node_schedule = [template_node, *epilogue_nodes]

        if config.benchmark_kernel:
            num_gb = kernel.estimate_kernel_num_bytes() / 1e9
            grid_args = V.graph.sizevars.optimization_hints(kernel.call_sizes)
            assert kernel.meta is not None, "meta is None"
            grid = kernel.grid_fn(*grid_args, kernel.meta)

            src_code = (
                f"{kernel.imports_for_benchmark_kernel()}\n"
                f"{src_code}\n"
                f"{kernel.codegen_kernel_benchmark(num_gb).getvalue()}"
            )

        if only_gen_src_code:
            return src_code
        traced_graph_hash = None
        kernel_name, src_code = self.define_kernel(src_code, node_schedule, kernel, traced_graph_hash)

    self.codegen_comment(node_schedule)
    kernel.call_kernel(kernel_name, template_node.node)

    V.graph.removed_buffers |= kernel.removed_buffers
    V.graph.inplaced_to_remove |= kernel.inplaced_to_remove
    self.scheduler.free_buffers()
    return None

def codegen_node(self, node: FusedSchedulerNode | SchedulerNode):
    removed_buffers = V.graph.removed_buffers.copy()
    inplaced_to_remove = V.graph.inplaced_to_remove.copy()
    try:
        return self._triton_scheduling.codegen_node(node)
    except Exception:
        log.debug(
            "index codegen for node %s failed, falling back to no-linear codegen",
            node,
            exc_info=True,
        )
    # A failed fused kernel may have marked intermediates as kernel-local.
    # Split fallback kernels need those buffers to be materialized again.
    V.graph.removed_buffers.clear()
    V.graph.removed_buffers.update(removed_buffers)
    V.graph.inplaced_to_remove.clear()
    V.graph.inplaced_to_remove.update(inplaced_to_remove)
    snodes = self._regroup_for_nolinear([node])
    groups = self._split_nolinear_nodes(snodes)
    return self._codegen_nolinear_groups(node, groups)
